  return mix(mix(cellValue(base),cellValue(base+vec2(1,0)),f.x),
             mix(cellValue(base+vec2(0,1)),cellValue(base+1.0),f.x),f.y);
}
float filings(vec2 st,float time) {
  vec2 cell=floor(st);
  float seed=cellValue(cell);
  vec2 offset=vec2(seed,cellValue(cell+17.3))*.60+.20;
  vec2 d=(fract(st)-offset)*vec2(.84,1.48);
  float size=.055+.19*seed*seed;
  float mark=1.0-smoothstep(size*.50,size+.065,length(d));
  return mark*smoothstep(.41,.89,seed)*(.24+.76*bell((fract(seed+time*.21)-.50)*4.8));
