            +.09*(1.0-shift);
  float width=.15+.068*sin(x*3.7+.65)+.068*shift;
  float v=(p.y-bed)/width;
  float under=bell(v*.96);
  float n=softNoise(vec2(x*3.8-t*.28,v*1.45+3.2));
  float ripple=softNoise(vec2(x*7.0-t*.68+1.2*n,v*2.7));
  float ridge=v+.48*sin(x*4.0-.49*t)+.28*(ripple-.5);
  float silverSeam=bell((ridge-.42)*13.0)*(.18+.82*n)
                  +.64*bell((ridge+.46)*19.0)*(.23+.77*ripple);
  float flow=n+.31*ripple+.16*v;
  float lamina=bell((flow-.64)*20.0)*under;
  float relight=bell((x-.73*sin(t*1.7+.42))/.43);
  float deposit=filings((p+vec2(.18*p.y,0))*vec2(103.0,78.0),t);
  float cloud=under*smoothstep(.16,.81,n+.22*ripple);
  vec3 bankColor=ceremony.y>2.5?vec3(.24,.40,.69):vec3(.14,.48,.46);
  vec3 cool=mix(pigment.rgb,bankColor,smoothstep(-.71,.88,x)*.65);
  vec3 light=cool*(cloud*.51+under*.095);
  light+=foilColor.rgb*(silverSeam*(.34+.45*relight)+lamina*(.12+.28*relight)
                       +deposit*under*(.38+.70*relight));
  float upper=.42-.20*x-.115*cos(3.65*x+.29*t);
  float bank=p.y-upper, far=bell((x+.65)*2.8);
  light+=mix(cool,foilColor.rgb,.53)*far*(.13*bell(bank*10.0)+.23*bell((bank+.008*n)*79.0))
         *(.33+.67*ripple);
