vec3 jadeTide(vec2 p,float t,float impulse) {
  float progress=1.-exp(-2.2*t);
  vec2 basin=(p-vec2(-.06,-.20))*vec2(.94,2.14);
  float radius=length(basin);
  float water=softNoise(p*vec2(5.2,8.)+vec2(-.18*t,.12*t));
  float ripple=radius+.065*(water-.5)+.026*sin(12.*p.x+5.*p.y-.62*t);
  float crest=ripple-(.36+.51*progress);
  float inner=crest+.19+.025*sin(9.*p.x+.37*t);
  float caustic=softNoise(vec2(15.*p.x+.8*water,18.*p.y-.46*t));
  float glint=smoothstep(.21,.79,caustic+.19*water);
  float fine=bell(crest/.024)+.60*bell(inner/.018);
  float depth=bell((crest+.055)/.18);
  vec3 emerald=mix(pigment.rgb,vec3(.19,.65,.43),water);
  return (emerald*(.39*depth+.14*bell(inner/.08))+
