  float body=bell(v*.84);
  float crest=v-.43+.27*(n-.5)+.13*sin(x*9.0-.5*t);
  float tooth=softNoise(vec2(12.3*x-.12*t,5.1*v+.91*n));
  float gild=bell((crest+.12*(tooth-.5))*12.3)*(.05+.95*smoothstep(.31,.73,fiber+.10*n));
  float broken=bell((v+.11+.61*(n-.5))*6.0)*smoothstep(.48,.78,fiber);
  float leaf=filings((p+vec2(.26*p.y,0))*vec2(81.0,69.0),t);
  float travel=bell((x+.75-t*.89)*2.35);
