  float travel=bell((x+.78-.88*t)*2.);
  float striae=bell(18.*(arc-.056-.06*sin(7.*x)))+.58*bell(31.*(arc+.082));
  vec3 iridescence=.59+.39*cos(6.28318*(vec3(.02,.73,.52)+.46+.27*x+.17*t+.16*cloud));
  vec3 field=pigment.rgb*(.11+.38*cloud)*envelope;
  field+=mix(iridescence,foilColor.rgb,.27)*striae*(.13+.38*travel)*(.27+.73*facet);
  vec2 grid=(p+vec2(.16*y,0))*vec2(17.,13.), cell=floor(grid);
  float seed=cellValue(cell);
  vec2 pt=fract(grid)-(.17+.65*vec2(seed,cellValue(cell+13.7)));
  float gleam=bell((fract(.22*t+seed)-.48)*4.8)*smoothstep(.66,.94,seed);
  float cut=bell(17.*pt.x)*bell(5.4*pt.y)+bell(5.4*pt.x)*bell(20.*pt.y);
  field+=foilColor.rgb*cut*gleam*(.17+.91*envelope);
  return field*(1.+.19*impulse);
}
vec3 solarLeaf(vec2 p,float time,float impulse) {
  vec2 q=p*vec2(.93,.79);
  float radius=length(q);
  float azimuth=atan(q.y,q.x);
  float opened=1.-exp(-3.2*time);
  float band=radius-(.44+.16*opened);
  float light=.35+.65*pow(.5+.5*cos(azimuth*2.-time*.94),3.);
  float fluting=cos(azimuth*73.+sin(3.*azimuth)*2.);
  float edge=bell(band*54.)*(.38+.62*smoothstep(-.3,.65,fluting));
  float inner=bell((band+.042)*90.)*(.54+.46*cos(6.*azimuth));
  float goldDust=filings(p*vec2(57.,46.),time)*bell(band*5.8);
  float halo=bell(band*6.)*(.12+.17*impulse);
  return pigment.rgb*halo+foilColor.rgb*light*(.72*edge+.48*inner+.74*goldDust);
}
vec4 frag () {
  vec2 p=(uv-0.5)*vec2(2.0,-2.0);
  float t=max(0.0,ceremony.x), theme=ceremony.y;
  float border=(1.0-smoothstep(.74,.99,abs(p.x)))*(1.0-smoothstep(.76,.99,abs(p.y)));
  if(border<.002) return vec4(0.0);
  vec3 light;
  if(theme>4.5) light=solarLeaf(p,t,ceremony.w);
  else if(theme>3.5) light=nacre(p,t,ceremony.w);
  else if(theme>1.5 && theme<2.5) light=lacquer(p,t,ceremony.w);
  else if(theme<1.5) light=jadeTide(p,t,ceremony.w);
  else light=river(p,t,ceremony.w);
  float edge=smoothstep(.20,.62,max(abs(p.x),abs(p.y)*.76));
  float wash=1.0-smoothstep(.12,1.0,abs(p.x)-(.12+1.19*(1.0-exp(-t*5.5))));
  return vec4(light*(.18+.82*edge)*wash*border*ceremony.z*tint.a,0.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

